"""Topic path subscription matcher."""
import re

def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    # Replace ** with .* to match any number of segments
    pattern = subscribed_pattern.replace("**", ".*")
    # Replace * with [^:]* to match exactly one segment
    pattern = pattern.replace("*", "[^:]*")
    # Add ^ and $ to match the entire string
    pattern = f"^{pattern}$"
    return re.match(pattern, event_topic) is not None

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return "*" in pattern.strip()
